async function imagenParaCanvas(file){
  if(typeof createImageBitmap==="function"){try{return await createImageBitmap(file,{imageOrientation:"from-image"})}catch(e){}}
  return await new Promise((resolve,reject)=>{const u=URL.createObjectURL(file),im=new Image();im.onload=()=>{URL.revokeObjectURL(u);resolve(im)};im.onerror=()=>{URL.revokeObjectURL(u);reject(new Error("No se pudo leer la imagen."))};im.src=u});
}
async function prepararFotoCatalogo(file){
  if(!file||!String(file.type||"").startsWith("image/"))throw new Error("Selecciona una imagen válida.");
  const img=await imagenParaCanvas(file),w0=Number(img.width||img.naturalWidth||0),h0=Number(img.height||img.naturalHeight||0);
  if(!w0||!h0){if(img.close)img.close();throw new Error("No se pudieron leer las dimensiones de la imagen.")}
  const max=1600,escala=Math.min(1,max/Math.max(w0,h0)),w=Math.max(1,Math.round(w0*escala)),h=Math.max(1,Math.round(h0*escala));
  const c=document.createElement("canvas");c.width=w;c.height=h;const ctx=c.getContext("2d");ctx.drawImage(img,0,0,w,h);if(img.close)img.close();
  const blob=await new Promise(resolve=>c.toBlob(resolve,"image/jpeg",.84));if(!blob)throw new Error("No se pudo preparar la fotografía.");
  const nombre=limpiarNombreArchivo(String(file.name||"foto").replace(/\.[^.]+$/,""))+".jpg";
  return {id:"tmp_"+Date.now()+"_"+Math.random().toString(36).slice(2,8),blob,nombre,preview:URL.createObjectURL(blob),principal:false};
}
