function esquemaClimatizacionSVG(p){if(!especialidadesProyecto(p).includes("climatizacion"))return "";const gens=GENERADORES.filter(g=>!(g.existente!==false&&g.se_retira)),ems=listaEmisores(p),C=ZX_ESQUEMAS.colores;if(!gens.length&&!ems.length)return "";
  const n=Math.max(gens.length,ems.length,1),h=Math.max(310,150+n*70),y0=118,step=70,centerX=178;let gRows="",eRows="";
  gens.forEach((g,i)=>{const y=y0+i*step,nombre=[textoGenerador(g.tipo),g.marca,g.modelo].filter(Boolean).join(" · "),serv=listaFunciones(g.funciones).map(x=>({calefaccion:"Cal.",acs:"ACS",refrigeracion:"Ref.",piscina:"Pisc."}[x]||x)).join(" / "),rol=textoRol(g.tecnico_meta&&g.tecnico_meta.rol_futuro);gRows+=`<rect x="16" y="${y-24}" width="132" height="54" rx="10" fill="${C.climatizacionSuave}" stroke="${C.climatizacion}"/>${zxSvgLineas(nombre,26,y-5,20,9.5,800,C.texto,10)}<text x="26" y="${y+17}" font-size="7.8" fill="${C.secundario}">${g.potencia_kw!=null?limpiar(g.potencia_kw)+" kW · ":""}${limpiar(rol).slice(0,14)}${serv?" · "+limpiar(serv).slice(0,16):""}</text><path d="M 148 ${y+2} H ${centerX}" stroke="${C.climatizacion}" stroke-width="3" fill="none"/>`});
  ems.forEach((e,i)=>{const y=y0+i*step,nombre=textoEmisor(e.tipo),temp=[e.impulsion_c!=null?e.impulsion_c:null,e.retorno_c!=null?e.retorno_c:null].filter(v=>v!=null).join("/");eRows+=`<path d="M ${centerX} ${y+2} H 210" stroke="${C.climatizacion}" stroke-width="3" fill="none"/><rect x="210" y="${y-24}" width="134" height="54" rx="10" fill="#fff" stroke="${C.borde}"/>${zxSvgLineas(nombre,220,y-5,20,9.5,800,C.texto,10)}<text x="220" y="${y+17}" font-size="7.8" fill="${C.secundario}">${limpiar(e.zona||"zona por definir").slice(0,16)}${temp?" · "+limpiar(temp)+" °C":""}${e.potencia_kw!=null?" · "+limpiar(e.potencia_kw)+" kW":""}</text>`});
  return `<section class="zx_pr_section"><div class="zx_pr_section_head"><div><h3>Esquema funcional de climatización</h3><span>Generadores, servicios y emisores según los datos actuales</span></div></div><div class="zx_pr_scheme_wrap zx_pr_scheme_wrap_drain"><svg class="zx_pr_scheme zx_pr_scheme_drain" viewBox="0 0 360 ${h}" role="img" aria-label="Esquema funcional de climatización"><rect width="360" height="${h}" rx="18" fill="#fff"/><text x="16" y="28" font-size="15" font-weight="800" fill="${C.texto}">Esquema técnico · climatización</text><rect x="16" y="42" width="116" height="24" rx="12" fill="${C.climatizacionSuave}"/><text x="28" y="58" font-size="9.5" font-weight="800" fill="${C.climatizacion}">Circuito térmico</text><rect x="150" y="78" width="56" height="${Math.max(86,n*step-12)}" rx="12" fill="#f8fafc" stroke="${C.borde}"/><text x="160" y="96" font-size="8" font-weight="800" fill="${C.secundario}">RED /</text><text x="157" y="108" font-size="8" font-weight="800" fill="${C.secundario}">CONTROL</text>${gRows}${eRows}<text x="16" y="${h-18}" font-size="8.2" fill="${C.secundario}">Esquema funcional preliminar: conexiones hidráulicas exactas, bombas, depósitos y válvulas se completarán con el diseño por tramos.</text></svg></div></section>`}
